/// <summary>
/// CB616_TMSEngineSOCancellation
/// Class to proceede with the cancellation process for TMS engine
/// </summary>
internal final class METTMSEngineSalesOrderCancellation
{
    TMSCarrierCode      carrierCode;
    InventLocationId    inventLocationId;
    SalesTable          salesTable;
    int i;

}

Method.Source:
/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
internal void init(SalesTable    _salesTable)
{
    salesTable          = _salesTable;
    carrierCode         = TMSSalesTable::find(_salesTable.SalesId).CarrierCode;
}

/// <summary>
/// Validate TMS engine in On on the warehouse
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
private boolean useTMSEngine()
{
    METInventLocation   metInventLocation = METInventLocation::findByInventLocationId(salesTable.InventLocationId);
    return metInventLocation.IsTMSEngineUsed; 
}

/// <summary>
/// Validate if Perishable SOs are excluded from TMS
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
private boolean excludePerishable()
{
    return METInventLocation::findByInventLocationId(salesTable.InventLocationId).ExcludePerishables;
}

    /// <summary>
    /// Run the TMS cancellation
    /// </summary>
    public void run()
    {
        METTMSShipmentOrderTable    tMSShipmentOrderTable;
        METTMSShipmentOrderTable    tMSShipmentOrderTableExist;
        METTMSShipmentTable         tMSShipmentTable;
        boolean                     isSalesOrderPerishable = salesTable.METIsSalesOrderPerishable();

        if (!salesTable.METIsSalesOrderExcluded() &&
            carrierCode &&
            this.useTMSEngine() &&
            (!isSalesOrderPerishable ||
            (isSalesOrderPerishable  && !this.excludePerishable())))
        {
            try
            {
                ttsbegin;
                while select forupdate tMSShipmentOrderTable
                    where tMSShipmentOrderTable.OrderNumber == salesTable.SalesId
                {
                    tMSShipmentTable = METTMSShipmentTable::find(tMSShipmentOrderTable.ShipmentId, true);
                    tMSShipmentOrderTable.delete();

                    tMSShipmentTable.TMSSendStatus = METTMSSendStatus::ToBeSent;

                    select firstonly RecId from tMSShipmentOrderTableExist 
                        where tMSShipmentOrderTableExist.ShipmentId == tMSShipmentTable.ShipmentID
                        && tMSShipmentOrderTableExist.RecId != tMSShipmentOrderTable.RecId;
                    if (!tMSShipmentOrderTableExist.RecId)
                    {
                        
                        tMSShipmentTable.ShipmentStatus = METCashShipmentStatus::Cancelled;
                    }
                    tMSShipmentTable.update();
                }

                ttscommit;
            }
            catch (Exception::Error)
            {
                //SO should stay canceled even though TMS engine cancellation failed
                error("@MET:TMSEngineSOCancellationError");
            }
        }
    }

/// <summary>
/// Construct the class
/// </summary>
/// <returns>METTMSEngineSalesOrderCancellation</returns>
static METTMSEngineSalesOrderCancellation construct()
{
    return new METTMSEngineSalesOrderCancellation();
}

    /// <summary>
    /// main method
    /// </summary>
    /// <param name = "_args">args</param>
    public static void main(Args _args)
    {
        METTMSEngineSalesOrderCancellation tmsEngineSalesOrderCancellation = METTMSEngineSalesOrderCancellation::construct();

        if (_args.record() && _args.record().TableId == tableNum(SalesTable))
        {
            SalesTable  salesTable = _args.record();
            if (salesTable.SalesStatus == SalesStatus::Canceled)
            {
                tmsEngineSalesOrderCancellation.init(_args.record());
                tmsEngineSalesOrderCancellation.run();
            }
        }
        else
        {
            throw error(strfmt("@SYS29104", funcname())); // Class %1 must be called with a buffer.
        }
    }
